/* Message translation for the yaif command line. The table (yaif_msgs.h) is generated by i18n/gen.py from
   i18n/<lang>.tsv, keyed by the English text; a message with no translation prints in English.
   Language: YAIF_LANG, else LC_ALL / LC_MESSAGES / LANG (Windows: the display language). "C", "POSIX", unset: English. */
#ifndef YAIF_I18N_H
#define YAIF_I18N_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#ifdef _WIN32
#include <windows.h>
#endif

#ifndef __EMSCRIPTEN__
#include "yaif_msgs.h"
#else
#define YI_NLANG 0
static const char *const yi_names[1] = {0};
static const struct { const char *en; const char *tr[1]; } yi_tab[1] = {{0, {0}}};
#define YI_NKEYS 0
#endif

static int yi_col = -2;   /* -2 not decided yet, -1 English */

#ifdef _WIN32
static UINT yi_old_cp;
static void yi_restore_cp(void) { SetConsoleOutputCP(yi_old_cp); }
#endif

static int yi_find(const char *name) {
  int i;
  for (i = 0; i < YI_NLANG; i++) if (!strcmp(yi_names[i], name)) return i;
  return -1;
}

/* "fr_FR.UTF-8", "pt_BR", "zh_TW", "de" -> a column, or -1 */
static int yi_parse(const char *s) {
  char l[16] = {0}, r[16] = {0};
  int i = 0, j = 0;
  if (!s || !*s) return -1;
  while (s[i] && s[i] != '_' && s[i] != '-' && s[i] != '.' && s[i] != '@' && i < 15) { l[i] = (s[i] >= 'A' && s[i] <= 'Z') ? s[i] + 32 : s[i]; i++; }
  if (s[i] == '_' || s[i] == '-') { i++; while (s[i] && s[i] != '.' && s[i] != '@' && j < 15) { r[j] = (s[i] >= 'a' && s[i] <= 'z') ? s[i] - 32 : s[i]; i++; j++; } }
  if (!strcmp(l, "c") || !strcmp(l, "posix") || !strcmp(l, "en")) return -1;
  if (!strcmp(l, "zh")) return yi_find((!strcmp(r, "TW") || !strcmp(r, "HK") || !strcmp(r, "MO") || !strcmp(r, "HANT")) ? "zh_Hant" : "zh_Hans");
  if (!strcmp(l, "pt") && !strcmp(r, "BR")) return yi_find("pt_BR");
  if (!strcmp(l, "nb") || !strcmp(l, "nn")) return -1;
  return yi_find(l);
}

static int yi_pick(void) {
  const char *e = getenv("YAIF_LANG");
  int c = -1;
  if (e && *e) c = yi_parse(e);
  else {
#ifdef _WIN32
    LANGID id = GetUserDefaultUILanguage();
    switch (id & 0x3ff) {
      case 0x0c: c = yi_find("fr"); break;  case 0x0a: c = yi_find("es"); break;
      case 0x07: c = yi_find("de"); break;  case 0x10: c = yi_find("it"); break;
      case 0x16: c = yi_find(id == 0x0416 ? "pt_BR" : "pt"); break;
      case 0x13: c = yi_find("nl"); break;  case 0x19: c = yi_find("ru"); break;
      case 0x15: c = yi_find("pl"); break;  case 0x1f: c = yi_find("tr"); break;
      case 0x11: c = yi_find("ja"); break;  case 0x12: c = yi_find("ko"); break;
      case 0x04: c = yi_find((id == 0x0804 || id == 0x1004) ? "zh_Hans" : "zh_Hant"); break;
      case 0x01: c = yi_find("ar"); break;  case 0x39: c = yi_find("hi"); break;
      case 0x21: c = yi_find("id"); break;  case 0x2a: c = yi_find("vi"); break;
      case 0x22: c = yi_find("uk"); break;
    }
    /* the console prints OEM code pages by default: ask for UTF-8 for the run, give it back at exit */
    if (c >= 0 && GetConsoleOutputCP() != 65001) { yi_old_cp = GetConsoleOutputCP(); SetConsoleOutputCP(65001); atexit(yi_restore_cp); }
#else
    const char *v[3] = { getenv("LC_ALL"), getenv("LC_MESSAGES"), getenv("LANG") };
    int i;
    for (i = 0; i < 3; i++) if (v[i] && *v[i]) { c = yi_parse(v[i]); break; }
#endif
  }
  return c;
}

/* The translation of an English message, or the message itself. */
static const char *yi_tr(const char *en) {
  int lo = 0, hi = YI_NKEYS - 1;
  if (yi_col == -2) yi_col = yi_pick();
  if (yi_col < 0) return en;
  while (lo <= hi) {
    int mid = (lo + hi) / 2, c = strcmp(en, yi_tab[mid].en);
    if (!c) return yi_tab[mid].tr[yi_col] ? yi_tab[mid].tr[yi_col] : en;
    if (c < 0) hi = mid - 1; else lo = mid + 1;
  }
  return en;
}

/* The translation with %1 to %4 replaced by the arguments (whole sentences: word order differs). */
static const char *yi_fmt(const char *en, const char *a1, const char *a2, const char *a3, const char *a4) {
  static char buf[4][8192];
  static int k;
  const char *t = yi_tr(en), *a[4] = { a1, a2, a3, a4 };
  char *o = buf[k = (k + 1) & 3];
  size_t n = 0, cap = sizeof buf[0] - 1;
  for (; *t && n < cap; t++) {
    if (t[0] == '%' && t[1] >= '1' && t[1] <= '4') {
      const char *s = a[t[1] - '1'];
      t++;
      while (s && *s && n < cap) o[n++] = *s++;
    } else o[n++] = *t;
  }
  o[n] = 0;
  return o;
}
#endif
